"""Offline interactive rotor inspector: no network or JavaScript dependencies."""
import json
from pathlib import Path


def write_preview(geometry, report, config, output):
    s=geometry.samples
    data={"vertices":geometry.mesh.vertices.tolist(),"faces":geometry.mesh.faces.tolist(),
          "curve":s["C"].tolist(),"sections":s["points"].tolist(),"flow":s["section_flow"].tolist(),
          "u":s["u"].tolist(),"chordFlow":s["chord_flow"].tolist(),"width":s["width"].tolist(),
          "curvature":s["curvature"].tolist(),"measurements":geometry.measurements,
          "report":report.to_dict(),"parameters":config["parameters"]}
    path=Path(output);path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(HTML.replace("__DATA__",json.dumps(data,allow_nan=False).replace("</","<\\/")))
    return path


HTML='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Loop Lab · Rotor inspector</title><style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#0b111b;color:#dfe9f4}*{box-sizing:border-box}body{margin:0}header{padding:25px 32px;border-bottom:1px solid #293648;display:flex;justify-content:space-between;align-items:center}h1{font-size:22px;margin:0;letter-spacing:-.6px}header p{margin:5px 0 0;color:#8fa0b8;font-size:13px}.tag{border:1px solid #4c7990;color:#83e4d9;border-radius:20px;padding:7px 12px;font-size:12px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;height:calc(100vh - 96px)}main{position:relative;min-height:420px;background:radial-gradient(ellipse at 50% 40%,#1c3044,#0b111b 75%)}canvas{width:100%;height:100%;display:block;touch-action:none}.tools{position:absolute;top:18px;left:20px;display:flex;gap:7px;flex-wrap:wrap}button{background:#172536;color:#c7d5e7;border:1px solid #34475d;border-radius:7px;padding:8px 12px;cursor:pointer}button:hover{border-color:#65d4c6;color:white}.hint{position:absolute;bottom:16px;left:22px;color:#7f94ac;font-size:12px}aside{overflow:auto;border-left:1px solid #293648;padding:24px}.eyebrow{font-size:10px;letter-spacing:1.8px;color:#74d5c7;margin-bottom:12px}.metric{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #253447;font-size:13px}.metric span{color:#8fa0b8}h2{font-size:14px;margin:24px 0 12px}input{width:100%;accent-color:#77dccc}.warning{font-size:12px;line-height:1.6;color:#e6bc80;padding:11px;background:#2d251c;border-radius:6px;margin:10px 0}.small{font-size:12px;line-height:1.6;color:#8fa0b8}#flowbar{display:flex;height:13px;gap:1px;margin:12px 0}.tick{flex:1;cursor:pointer}.selected{outline:2px solid white}details{margin-top:18px}pre{font-size:11px;white-space:pre-wrap;color:#a8bad0}@media(max-width:800px){.layout{display:block;height:auto}main{height:60vh}aside{border-left:none}}
</style><header><div><h1>Loop Lab <span style="color:#6d859d;font-weight:400">/ rotor inspector</span></h1><p>Explicit airfoil sections · Analytic loop · Reproducible geometry</p></div><div class="tag" id="status"></div></header><div class="layout"><main><canvas id="view" aria-label="Interactive three dimensional rotor"></canvas><div class="tools"><button id="iso">Isometric</button><button id="top">Top</button><button id="side">Side</button><button id="surface">Surface / wire</button><button id="section">Inspect section</button></div><div class="hint">Drag to orbit · Scroll to zoom · Section colors show estimated flow direction, not performance</div></main><aside><div class="eyebrow">GEOMETRY SNAPSHOT</div><div id="metrics"></div><h2>Travel along the loop</h2><input id="station" type="range" min="0" value="0" aria-label="Section station"><div id="flowbar"></div><div class="small">Teal: flow along the chosen chord.<br>Amber: reverse flow. Gray: weak projection.</div><div id="local"></div><h2>Validation</h2><div id="warnings"></div><details><summary>Parameters & checks</summary><pre id="details"></pre></details><p class="small">No aerodynamic performance is inferred by this viewer. Relative flow omits induced velocity. Root retraction is not structural certification.</p></aside></div><script>
const data=__DATA__;
const c=document.getElementById('view'),ctx=c.getContext('2d');let yaw=-.7,pitch=.9,zoom=1,wire=false,inspect=false,index=0,drag=null;
const radius=Math.max(...data.vertices.map(v=>Math.hypot(...v)));let width,height;
const byId=id=>document.getElementById(id),fmt=(v,n=2)=>Number(v).toFixed(n);
byId('status').textContent=data.report.valid?(data.report.checks.self_intersection_scan==='completed'?'Geometry checks passed':'Preliminary checks only'):'Geometry needs attention';
const m=data.measurements;byId('metrics').innerHTML=[['Diameter',fmt(m.diameter*1000)+' mm'],['Volume',fmt(m.volume*1e6)+' cm³'],['Loop units',m.blade_count],['Triangles',m.triangles.toLocaleString()],['Reverse-flow stations',fmt(100*m.reverse_flow_station_fraction,0)+'%']].map(([k,v])=>`<div class="metric"><span>${k}</span><b>${v}</b></div>`).join('');
const warnings=[...data.report.violations.map(x=>x.code+': '+x.message),...data.report.warnings];for(const text of warnings){let el=document.createElement('div');el.className='warning';el.textContent=text;byId('warnings').append(el)}
byId('details').textContent=JSON.stringify({parameters:data.parameters,checks:data.report.checks},null,2);
byId('station').max=data.u.length-1;
function choose(i){index=i;byId('station').value=i;byId('local').innerHTML=[['Loop coordinate',fmt(data.u[i],3)],['Chord',fmt(data.width[i]*1000)+' mm'],['Curvature',fmt(data.curvature[i])+' m⁻¹'],['Chordwise flow',fmt(data.chordFlow[i])+' m/s']].map(([k,v])=>`<div class="metric"><span>${k}</span><b>${v}</b></div>`).join('');[...byId('flowbar').children].forEach((e,j)=>e.classList.toggle('selected',i===j));draw()}
data.chordFlow.forEach((f,i)=>{let e=document.createElement('div');e.className='tick';e.style.background=Math.abs(f)<.1?'#607084':f<0?'#d4a15b':'#65d1bd';e.title=`u=${fmt(data.u[i],3)}`;e.onclick=()=>choose(i);byId('flowbar').append(e)});
function transform(v){let x=v[0]*Math.cos(yaw)-v[1]*Math.sin(yaw),y=v[0]*Math.sin(yaw)+v[1]*Math.cos(yaw);return[x,y*Math.cos(pitch)-v[2]*Math.sin(pitch),y*Math.sin(pitch)+v[2]*Math.cos(pitch)]}
function screen(v){let q=transform(v),scale=Math.min(width,height)*.37*zoom/radius;return[width/2+q[0]*scale,height/2-q[1]*scale,q[2]]}
function line(points,color,size=1){ctx.beginPath();points.forEach((v,i)=>{const p=screen(v);i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])});ctx.strokeStyle=color;ctx.lineWidth=size;ctx.stroke()}
function draw(){if(!width)return;ctx.clearRect(0,0,width,height);let projected=data.vertices.map(screen);let faces=data.faces.map(f=>({f,z:(projected[f[0]][2]+projected[f[1]][2]+projected[f[2]][2])/3})).sort((a,b)=>a.z-b.z);for(const {f} of faces){const pts=f.map(i=>projected[i]);ctx.beginPath();ctx.moveTo(pts[0][0],pts[0][1]);ctx.lineTo(pts[1][0],pts[1][1]);ctx.lineTo(pts[2][0],pts[2][1]);ctx.closePath();if(!wire){let a=data.vertices[f[0]],b=data.vertices[f[1]],d=data.vertices[f[2]],u=b.map((x,i)=>x-a[i]),v=d.map((x,i)=>x-a[i]),n=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]],light=Math.abs(transform(n)[2])/(Math.hypot(...n)||1);ctx.fillStyle=`rgba(${40+45*light},${99+77*light},${112+66*light},${inspect?.18:1})`;ctx.fill()}else{ctx.strokeStyle='#569eaa55';ctx.lineWidth=.5;ctx.stroke()}}
line(data.curve,'#f6cb7e',2);let ring=data.sections[index];line([...ring,ring[0]],'#ffffff',3);let start=data.curve[index],flow=data.flow[index],len=Math.hypot(...flow);if(len>.1)line([start,start.map((v,i)=>v+flow[i]/len*radius*.25)],'#ec9a76',3);for(let axis=0;axis<3;axis++){let end=[0,0,0];end[axis]=radius*.35;line([[0,0,0],end],['#f18c89','#83d7b2','#8ab7f7'][axis],2);let pos=screen(end);ctx.fillStyle='#c8d8e8';ctx.fillText(['x','y','z'][axis],pos[0]+4,pos[1])}}
function resize(){const r=c.getBoundingClientRect(),dpr=devicePixelRatio||1;width=r.width;height=r.height;c.width=width*dpr;c.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
c.onpointerdown=e=>{drag=[e.clientX,e.clientY];c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(drag){yaw+=(e.clientX-drag[0])*.008;pitch+=(e.clientY-drag[1])*.008;drag=[e.clientX,e.clientY];draw()}};c.onpointerup=()=>drag=null;c.onwheel=e=>{e.preventDefault();zoom=Math.max(.3,Math.min(4,zoom*Math.exp(-e.deltaY*.001)));draw()};byId('station').oninput=e=>choose(+e.target.value);byId('top').onclick=()=>{pitch=0;yaw=0;draw()};byId('side').onclick=()=>{pitch=Math.PI/2;yaw=0;draw()};byId('iso').onclick=()=>{pitch=.9;yaw=-.7;zoom=1;draw()};byId('surface').onclick=()=>{wire=!wire;draw()};byId('section').onclick=()=>{inspect=!inspect;draw()};window.onresize=resize;choose(Math.floor(data.u.length/3));resize();
</script></html>'''
